cat > /tmp/model.pl <<'EOF'
sub tolow { my $b=shift; return ($b>=0x41 && $b<=0x5A) ? $b+32 : $b; }
sub toup { my $b=shift; return ($b>=0x61 && $b<=0x7A) ? $b-32 : $b; }
sub humanize {
  my @b = unpack("C*", shift);
  for my $i (0..$#b) { $b[$i]=0x20 if $b[$i]==0x5F; }
  if (@b) { $b[0]=toup($b[0]); }
  return pack("C*",@b);
}
sub titleize {
  my @in = unpack("C*", shift);
  my @out; my $cap=1;
  for my $c (@in) {
    if ($c==0x20) { push @out,0x20; $cap=1; }
    elsif ($cap) { push @out, toup($c); $cap=0; }
    else { push @out, tolow($c); }
  }
  return pack("C*",@out);
}
1;
EOF
