  next if $inp =~ /\x0a/;   # newline shifts line indexing
  my @args=($bin,$inp);
  my $out = do {
    open(my $fh,"-|",@args) or die "fork: $!";
    local $/; my $d=<$fh>; close($fh); $d;
  };
  $n++;
  if (!defined $out) { printf("NOOUT %s\n",$l); $bad++; next; }
  my @lines = split(/\n/, $out, -1);
